import sqlite3, json
from collections import defaultdict, deque

con = sqlite3.connect('file:/home/user/guidebook/data/guidebook.db?mode=ro', uri=True)
tables = [r[0] for r in con.execute("select name from sqlite_master where type='table' order by name")]
counts = {t: con.execute(f'select count(*) from "{t}"').fetchone()[0] for t in tables}
empty = {t for t in tables if counts[t] == 0}

dep = defaultdict(set)
for t in tables:
    info = {row[1]: row for row in con.execute(f'PRAGMA table_info("{t}")')}
    for fk in con.execute(f'PRAGMA foreign_key_list("{t}")').fetchall():
        _id, seq, ref_table, from_col, to_col, on_update, on_delete, match = fk
        notnull = info[from_col][3]
        if notnull == 1 and ref_table != t:
            dep[t].add(ref_table)

NO_WRITER_EVER = {"items", "reasoning_doc_citations", "spec_value_probes",
                   "case_study_outcomes", "case_study_populations", "case_study_specs",
                   "case_study_strategies", "citation_population_links",
                   "economics_entry_populations", "economics_entry_specs",
                   "external_root_registry", "extraction_population_links",
                   "item_bpc_links", "item_population_elaborations", "item_taxonomy_links",
                   "probe_population_links", "reference_stubs", "room_items",
                   "search_coverage", "search_languages", "situations",
                   "source_slug_links", "term_item_links"}

# reverse-reachability: which tables transitively NOT-NULL-depend (directly or indirectly)
# on each permanently-unfillable (no writer) empty table?
rev = defaultdict(set)
for t, ds in dep.items():
    for d in ds:
        rev[d].add(t)

def transitive_dependents(root):
    seen = set()
    q = deque([root])
    while q:
        u = q.popleft()
        for v in rev.get(u, ()):
            if v not in seen:
                seen.add(v)
                q.append(v)
    return seen

print("=== Tables PERMANENTLY unwritable because they transitively NOT-NULL-depend on a target with NO writer at all ===")
permanently_blocked_root = {}
for root in sorted(NO_WRITER_EVER & empty):
    deps = transitive_dependents(root)
    if deps:
        print(f"-- via {root} --")
        for d in sorted(deps):
            print(f"   {d}")
            permanently_blocked_root.setdefault(d, set()).add(root)

print()
print("=== Full permanently-blocked set (dependents of a no-writer target), size ===")
print(len(permanently_blocked_root))
for t in sorted(permanently_blocked_root):
    print(f"  {t}  <= blocked by: {sorted(permanently_blocked_root[t])}")

# Topological order (Kahn's algorithm) over the whole dep graph (dep[t] = must-be-filled-before)
indeg = {t: len(dep.get(t, ())) for t in tables}
order = []
avail = deque([t for t in tables if indeg[t] == 0])
indeg2 = dict(indeg)
# need reverse: for Kahn on "t depends on dep[t]", process nodes with no unresolved deps first
remaining_deps = {t: set(dep.get(t, ())) for t in tables}
placed = set()
order = []
progress = True
while progress:
    progress = False
    for t in tables:
        if t in placed:
            continue
        if remaining_deps[t] <= placed:
            order.append(t)
            placed.add(t)
            progress = True
if len(placed) != len(tables):
    print("WARNING: not all tables placed -> real cycle exists among", set(tables)-placed)

print()
print("=== TOPOLOGICAL FILL ORDER (a valid one; ties broken by table name) ===")
for i, t in enumerate(order, 1):
    tag = ""
    if t in empty:
        tag = " [EMPTY now]"
        if t in NO_WRITER_EVER:
            tag += " [NO WRITER -> permanent]"
    print(f"{i:2d}. {t}{tag}")
